-- id:       view-full-detail
-- title:    Slowest resolutions (view with a derived attribute)
-- concept:  vw_complaint_full_detail · resolution_time = resolved_at − created_at
-- rubric:   8 · View
-- purpose:  The Lab 4 full-detail view on schema v2. resolution_time is the derived attribute from the ER diagram: computed in the view, never stored.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT complaint_id, title, department_name, ward_name,
       assigned_to_name, resolution_time, resolved_within_sla
FROM vw_complaint_full_detail
WHERE resolved_at IS NOT NULL
ORDER BY resolution_time DESC
LIMIT 10;
